<script>
import serverUrl from '../../config'
import { mapActions, mapGetters } from "vuex";
import io from "socket.io-client";
import * as types from "../../store/types";

export default {
  name: 'FriendRequests',

  data() {
    return {
      socket: io(serverUrl, {
        query: { token: localStorage.getItem("token") },
      }),
      loadingAccept: null,
      loadingDecline: null,
      snackbar: false,
      snackbarText: '',
      snackbarColor: 'success',
      snackbarIcon: 'mdi-check-circle',

      // Swipe functionality
      touchStartX: 0,
      touchCurrentX: 0,
      swipingId: null,
      swipeThreshold: 80,

      // Profile preview
      profileDialog: false,
      selectedUser: null,

      // Local list management
      localFriendRequests: [],
      lastRemovedUser: null,
      lastAction: null,

      // Snackbars
      undoSnackbar: false,
      undoMessage: '',
      newRequestSnackbar: false,
      newRequestUser: null,
    };
  },

  computed: {
    ...mapGetters({
      httpFriendRequest: types.GET_FRIEND_REQUEST,
    }),

    displayRequests() {
      return this.localFriendRequests;
    },
  },

  watch: {
    httpFriendRequest: {
      immediate: true,
      handler(newVal, oldVal) {
        // Initial load: copy from Vuex
        if (this.localFriendRequests.length === 0 && newVal && newVal.length > 0) {
          this.localFriendRequests = [...newVal];
          return;
        }

        // When Vuex changes: merge new items into local list
        if (oldVal && newVal && newVal.length > oldVal.length) {
          const newItems = newVal.filter(
            nv => !this.localFriendRequests.some(lv => lv.id === nv.id)
          );
          if (newItems.length > 0) {
            this.localFriendRequests = [...newItems, ...this.localFriendRequests];
            this.newRequestUser = newItems[0];
            this.newRequestSnackbar = true;
          }
        }

        // If Vuex has fewer items (e.g., accepted elsewhere), sync down
        if (oldVal && newVal && newVal.length < oldVal.length) {
          this.localFriendRequests = this.localFriendRequests.filter(
            lv => newVal.some(nv => nv.id === lv.id)
          );
        }
      }
    }
  },

  methods: {
    ...mapActions({
      request: types.GET_FRIEND_REQUEST,
    }),

    // ===== Local List Management =====

    removeFromLocalList(userId) {
      const index = this.localFriendRequests.findIndex(u => u.id === userId);
      if (index > -1) {
        this.lastRemovedUser = {
          user: { ...this.localFriendRequests[index] },
          index: index
        };
        this.localFriendRequests.splice(index, 1);
      }
    },

    restoreUser() {
      if (this.lastRemovedUser) {
        this.localFriendRequests.splice(this.lastRemovedUser.index, 0, this.lastRemovedUser.user);
        this.lastRemovedUser = null;
      }
    },

    // ===== Actions =====

    async addFriend(id) {
      this.loadingAccept = id;
      this.lastAction = 'accept';
      try {
        this.removeFromLocalList(id);
        this.undoMessage = 'Friend request accepted';
        this.undoSnackbar = true;

        await this.$store.dispatch(types.SUBMIT_FRIEND_REQUEST, id);
        this.$store.commit(types.REMOVE_ADD_REQUEST, id);
        this.showSnackbar('Friend request accepted!', 'success', 'mdi-check-circle');
      } catch (error) {
        this.restoreUser();
        this.showSnackbar('Something went wrong', 'error', 'mdi-alert-circle');
      } finally {
        this.loadingAccept = null;
        setTimeout(() => { this.undoSnackbar = false; }, 500);
      }
    },

    async removeRequestOne(id) {
      this.loadingDecline = id;
      this.lastAction = 'delete';
      try {
        this.removeFromLocalList(id);
        this.undoMessage = 'Friend request deleted';
        this.undoSnackbar = true;

        await this.$store.dispatch(types.REMOVE_ADD_REQUEST_ONE, id);
        this.showSnackbar('Request removed', 'info', 'mdi-delete');
      } catch (error) {
        this.restoreUser();
        this.showSnackbar('Something went wrong', 'error', 'mdi-alert-circle');
      } finally {
        this.loadingDecline = null;
        setTimeout(() => { this.undoSnackbar = false; }, 500);
      }
    },

    undoLastAction() {
      this.restoreUser();
      this.undoSnackbar = false;
      this.showSnackbar('Action undone', 'info', 'mdi-undo');
    },

    // ===== Swipe =====

    handleTouchStart(event, userId) {
      this.touchStartX = event.touches[0].clientX;
      this.swipingId = userId;
      this.touchCurrentX = this.touchStartX;
    },

    handleTouchMove(event, userId) {
      if (this.swipingId !== userId) return;
      this.touchCurrentX = event.touches[0].clientX;
      const diff = this.touchCurrentX - this.touchStartX;
      if (Math.abs(diff) > 150) {
        this.touchStartX = this.touchCurrentX - (diff > 0 ? 150 : -150);
      }
    },

    handleTouchEnd(userId) {
      const diff = this.touchCurrentX - this.touchStartX;

      if (Math.abs(diff) > this.swipeThreshold) {
        if (diff < -this.swipeThreshold) {
          this.lastAction = 'delete';
          this.undoMessage = 'Friend request deleted';
          this.undoSnackbar = true;
          this.removeRequestOne(userId);
        } else if (diff > this.swipeThreshold) {
          this.lastAction = 'accept';
          this.undoMessage = 'Friend request accepted';
          this.undoSnackbar = true;
          this.addFriend(userId);
        }
      }

      this.swipingId = null;
      this.touchStartX = 0;
      this.touchCurrentX = 0;
    },

    getSwipeStyle(userId) {
      if (this.swipingId !== userId) return {};
      const diff = this.touchCurrentX - this.touchStartX;
      return {
        transform: `translateX(${diff}px)`,
        transition: 'none'
      };
    },

    // ===== Helpers =====

    showSnackbar(text, color, icon) {
      this.snackbarText = text;
      this.snackbarColor = color;
      this.snackbarIcon = icon;
      this.snackbar = true;
    },

    handleImageError(event) {
      event.target.src = 'data:image/svg+xml;base64,';
    },

    openProfilePreview(user) {
      this.selectedUser = user;
      this.profileDialog = true;
    },

    getRandomStat(min = 10, max = 200) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    },

    getMutualAvatars(userId) {
      return [
        `https://i.pravatar.cc/40?img=${userId % 10 + 1}`,
        `https://i.pravatar.cc/40?img=${(userId + 1) % 10 + 1}`,
        `https://i.pravatar.cc/40?img=${(userId + 2) % 10 + 1}`
      ];
    },

    getMutualCount(userId) {
      return (userId % 5) + 1;
    }
  },

  created() {
    // Initial load
    this.request().then(() => {
      if (this.httpFriendRequest && this.httpFriendRequest.length > 0) {
        this.localFriendRequests = [...this.httpFriendRequest];
      }
    });

    // Listen for new friend requests via Socket
    this.socket.on("get-fr-req-data", (data) => {
      console.log("friendRequest.vue - new request received:", data);

      // Re-fetch from backend
      this.$store.dispatch(types.GET_FRIEND_REQUEST);
      // The watcher on httpFriendRequest will handle merging into localFriendRequests
    });
  },

  beforeDestroy() {
    if (this.socket) this.socket.disconnect();
  }
};
</script>

